@@ -0,0 +1,47 @@
+import { useState, useSyncExternalStore } from 'react';
+import type { CanvasViewCommand } from '../../../../domain/core/diagrams/canvasView';
+import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
+import type { CanvasViewRequest } from './canvasViewReceiver';
+import './canvasViews.css';
+
+export function CanvasViewControls({ controller, onCommand, disabled, canvasName }: {
+  controller: MappingDocumentController; canvasName: string; disabled?: boolean; onCommand: (request: CanvasViewRequest) => Promise<unknown>;
+}) {
+  useSyncExternalStore(controller.subscribe, controller.getSnapshot);
+  const { saved, recording } = controller.canvasViews(), views = Object.values(saved);
+  const [name, setName] = useState(''), [selected, setSelected] = useState('');
+  const [busy, setBusy] = useState(false), [error, setError] = useState('');
+  const [retry, setRetry] = useState<CanvasViewRequest>();
+  const viewId = saved[selected] ? selected : views[0]?.id;
+  const send = async (request: CanvasViewRequest) => {
+    setBusy(true); setError('');
+    try { await onCommand(request); setRetry(undefined); }
+    catch (error) { const message = String(error); setError(message); setRetry(message.includes('PERSISTENCE_PENDING') ? request : undefined); }
+    finally { setBusy(false); }
+  };
+  const command = (input: CanvasViewCommand) => {
+    controller.settlePendingGesture();
+    void send({ ...input, requestId: crypto.randomUUID(), expectedVersion: controller.getSnapshot().version });
+  };
+  return <section className="canvas-view-controls" aria-label="Canvas views" data-mapping-static-ui data-diagram-canvas-static-ui>
+    <h2>Views</h2>
+    <p>{canvasName}</p>
+    <fieldset disabled={disabled || busy || !!retry}>
+      {recording ? <span role="status">Recording: {recording.name}</span>
+        : <label>New view<input aria-label="Canvas view name" placeholder="View name" maxLength={120} value={name} onChange={event => setName(event.target.value)} /></label>}
+      <button type="button" aria-pressed={!!recording} disabled={!recording && !name.trim()}
+        onClick={() => command(recording ? { operation: 'stop' } : { operation: 'start', name })}>{recording ? 'Stop & save' : 'Record view'}</button>
+      {recording && <button type="button" onClick={() => command({ operation: 'cancel' })}>Cancel recording</button>}
+      <label>Saved views<select aria-label="Saved canvas view" value={viewId ?? ''} onChange={event => setSelected(event.target.value)} disabled={!views.length}>
+        {!views.length && <option value="">No saved views</option>}
+        {views.map(view => <option key={view.id} value={view.id}>{view.name}</option>)}
+      </select></label>
+      {viewId && <p>{saved[viewId].checkpointIds.length - 1} recorded {saved[viewId].checkpointIds.length === 2 ? 'change' : 'changes'}</p>}
+      <button type="button" disabled={!viewId || !!recording} onClick={() => command({ operation: 'apply', viewId })}>Apply view</button>
+      <button type="button" disabled={!viewId} onClick={() => command({ operation: 'delete', viewId })}>Delete view</button>
+    </fieldset>
+    <p>Record canvas changes, then stop to save. Apply restores a saved view in one undoable step.</p>
+    {retry && <button type="button" disabled={busy || disabled} onClick={() => void send(retry)}>Retry save</button>}
+    {error && <div role="alert">{error}</div>}
+  </section>;
+}
diff --git a/src/features/mapping/canvas-views/canvasViewReceiver.ts b/src/features/mapping/canvas-views/canvasViewReceiver.ts
new file mode 100644
index 00000000..b0598fd7
--- /dev/null
+++ b/src/features/mapping/canvas-views/canvasViewReceiver.ts
@@ -0,0 +1,35 @@
+import { canvasViewCommandSchema } from '../../../../domain/core/diagrams/canvasView';
+import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
+import { z } from 'zod';
+
+export const canvasViewRequestSchema = canvasViewCommandSchema.extend({ requestId: z.string().min(1).max(200),
+  expectedVersion: z.number().int().nonnegative().optional(), sessionId: z.string().optional() }).strict();
+export type CanvasViewRequest = z.infer<typeof canvasViewRequestSchema>;
+type Result = ReturnType<MappingDocumentController['canvasView']>;
+/** Retain the mutation receipt before flushing so a failed save never applies a view twice. */
+export class CanvasViewReceiver {
+  private receipts = new Map<string, { signature: string; result: Result; pending?: Promise<Result> }>();
+  async apply(documentId: string, raw: unknown, controller: MappingDocumentController, persist: () => Promise<void>) {
+    const { requestId, expectedVersion, sessionId: _, ...input } = canvasViewRequestSchema.parse(raw);
+    if (input.operation === 'list' || input.operation === 'read') {
+      const result = controller.canvasView(controller.getSnapshot().version, input);
+      return input.operation === 'read' ? { version: result.version, view: result.saved[input.viewId!] } : result;
+    }
+    if (expectedVersion === undefined) throw Error('expectedVersion is required for CanvasView changes');
+    const key = JSON.stringify([documentId, requestId]), signature = JSON.stringify({ input, expectedVersion });
+    let receipt = this.receipts.get(key);
+    if (receipt && receipt.signature !== signature) throw Error('REQUEST_ID_CONFLICT: CanvasView arguments differ');
+    if (!receipt) {
+      if (this.receipts.size >= 2000) throw Error('CanvasView receipt capacity reached; reload the workspace');
+      receipt = { signature, result: controller.canvasView(expectedVersion, input) };
+      this.receipts.set(key, receipt);
+    }
+    if (!receipt.pending) {
+      const current = receipt;
+      current.pending = Promise.resolve().then(persist).then(() => current.result).catch(error => {
+        throw Error(`PERSISTENCE_PENDING: CanvasView changed; retry the same request to save: ${String(error)}`);
+      }).finally(() => { current.pending = undefined; });
+    }
+    return receipt.pending;
+  }
+}
