import { canvasViewCommandSchema } from '../../core/diagrams/canvasView';
import { highlightColorSchema, highlightTargetsSchema } from '../../core/diagrams/diagramHighlight';
import { repositoryContextSchema } from '../../core/repositories/repository';
import { diffTreeInputSchema } from '../changes/diffTree';
import { generationBatchSchemas } from './diagramBatch';
import { editDiagramSchema, createDiagramSchema, extendDiagramSchema, diagramEditRunSchema } from './diagramEdit';
import { diagramMigrationSchema } from '../changes/diagramMigration';
import { diagramChangeSchema } from '../changes/diagramChangeSession';
import { diagramJumpSchema } from '../../core/diagrams/diagramJump';
import { z } from 'zod';
import { diagramConnectionSchema } from '../../core/diagrams/diagramConnection';
export const idSchema = z.string().min(1).max(200);
const point = z.object({ column: z.number().int().nonnegative(), row: z.number().int().nonnegative() }).strict();
const mapping = z.object({ id: idSchema, entityId: idSchema, sourceRangeIndex: z.number().int().nonnegative(), sourceRangeId: z.string().optional(), line: z.number().int().positive(), startColumn: z.number().int().positive(), endColumn: z.number().int().positive() }).strict();
const sourceRange = z.object({ id: idSchema, path: z.string().min(1), startLine: z.number().int().positive(), endLine: z.number().int().positive(), originalLines: z.array(z.string()), symbol: z.string().optional(), compactionId: z.string().optional() }).strict();
const evidence = z.record(z.string(), z.object({ id: idSchema, sourceId: idSchema.optional(), handle: z.string(), label: z.string(), category: z.enum(['state','interface-data-struct','operation']), summary: z.string(), sourceRanges: z.array(sourceRange) }).strict());
const sourceBinding = z.object({sourceId: idSchema, repositoryIdentity: z.string().min(1), domainProfileId: z.enum(['source-code','document']),
  corpus: z.discriminatedUnion('kind', [z.object({kind:z.literal('git-worktree'),root:z.string().min(1),revision:z.string().optional()}).strict(),
    z.object({kind:z.literal('filesystem-documents'),root:z.string().min(1)}).strict()])}).strict();
export const contentFields = { ascii: z.string().min(1).max(20000), structureKind: z.enum(['diagram', 'tree']).optional(), mappings: z.array(mapping).max(2000).optional(), evidence: evidence.optional(), source: sourceBinding.optional() };
export const sourceMappingsFields = { nodeId: idSchema, mappings: z.array(mapping).max(2000), evidence, source: sourceBinding.optional() };
export const setSourceMappingsSchema = z.object({ sessionId: idSchema, changeSessionId: idSchema.optional(), requestId: idSchema, expectedVersion: z.number().int().nonnegative(), ...sourceMappingsFields }).strict();
export const drawSchema = z.object({ sessionId: idSchema, changeSessionId: idSchema.optional(), requestId: idSchema, expectedVersion: z.number().int().nonnegative(), nodeId: idSchema.optional(), parentId: idSchema.optional(), position: point.optional(), ...contentFields }).strict();
export const saveSchema = z.object({ repositoryId: idSchema.optional(), sessionId: idSchema, changeSessionId: idSchema.optional(), requestId: idSchema, expectedVersion: z.number().int().nonnegative(), nodeId: idSchema.optional(), name: z.string().trim().min(1).max(120), representationId: idSchema.optional(), expectedRevisionId: idSchema.optional() }).strict();
export const searchSchema = z.object({ snapshot: z.enum(['baseline', 'proposed']).optional(), operation: z.enum(['search','read']), mode: z.enum(['text','node','code-reference']).optional(), query: z.string().max(1000).optional(), representationId: idSchema.optional(), revisionId: idSchema.optional(), sessionId: idSchema.optional(), changeSessionId: idSchema.optional(), nodeId: idSchema.optional(), offset: z.number().int().nonnegative().default(0), limit: z.number().int().min(1).max(100).default(20) }).strict();
export const diagramAgentContextToolSchema = z.object({ operation: z.enum(['prepare', 'read', 'delete']),
  sessionId: idSchema, nodeId: idSchema, requestId: idSchema,
  expectedVersion: z.number().int().nonnegative().optional(), expectedRevisionId: idSchema.optional() }).strict();
export const execSchema = z.object({ mode: z.enum(['batched', 'immediate']).default('batched').describe('Batched commits consecutive mutations together and returns compact receipts. Reads flush pending edits. Immediate preserves per-edit commits and full node results.'), code: z.string().min(1).max(30000), sessionId: idSchema.optional(), changeSessionId: idSchema.optional(), requestId: idSchema, expectedVersion: z.number().int().nonnegative().optional() }).strict();
export const apiSearchSchema = z.object({ query: z.string().max(1000).default('') }).strict();
export const createChangeSessionSchema = z.object({ diffTree: diffTreeInputSchema.optional(), repositoryId: idSchema.optional(), commits: z.array(z.string().min(1).max(200)).max(2000).default([]), head: z.string().min(1).max(200).optional(), comparisonBase: repositoryContextSchema.shape.comparisonBase, title: z.string().trim().min(1).max(200), description: z.string().max(100000).optional(), canvasId: idSchema.optional(), requestId: idSchema }).strict();
export const updateChangeSessionSchema = z.object({ diffTree: diffTreeInputSchema.optional(), changeSessionId: idSchema, requestId: idSchema, expectedVersion: z.number().int().nonnegative(), title: z.string().trim().min(1).max(200).optional(), status: z.enum(['draft','ready','archived']).optional(), changes: z.array(diagramChangeSchema).max(2000).optional(), migrations: z.array(diagramMigrationSchema).max(1000).optional(), action: z.enum(['undo','redo','reset']).optional(), documentId: idSchema.optional() }).strict();
export const acceptChangeSessionSchema = z.object({ changeSessionId: idSchema, requestId: idSchema, expectedVersion: z.number().int().nonnegative() }).strict();
const hunkPageFields = { offset: z.number().int().nonnegative().default(0), limit: z.number().int().min(1).max(100).default(50), includePatches: z.boolean().default(true) };
export const discoverDiffHunksSchema = z.object({ repositoryId: idSchema.optional(), commits: z.array(z.string().min(1).max(200)).max(2000).default([]), head: z.string().min(1).max(200).optional(), comparisonBase: repositoryContextSchema.shape.comparisonBase, ...hunkPageFields }).strict();
export const readDiffTreeSchema = z.object({ changeSessionId: idSchema, nodeIds: z.array(idSchema).max(2000).optional(), hunkIds: z.array(idSchema).max(2000).optional(), ...hunkPageFields }).strict().refine(input => !(input.nodeIds && input.hunkIds), 'Choose nodeIds or hunkIds');
export const canvasViewToolSchema = canvasViewCommandSchema.extend({ sessionId: idSchema, requestId: idSchema, expectedVersion: z.number().int().nonnegative().optional() }).strict();
export const agentToolSchemas = { 'canvas-view': canvasViewToolSchema, get_repository_diff_hunks: discoverDiffHunksSchema, read_change_session_diff_tree: readDiffTreeSchema, list_repositories: z.object({}).strict(), register_repository: z.object({ path: z.string().min(1), name: z.string().trim().min(1).max(120).optional(), requestId: idSchema }).strict(), 'diagram-agent-context': diagramAgentContextToolSchema, 'edit-diagram': z.union([editDiagramSchema, generationBatchSchemas['edit-diagram']]), 'create-diagram': z.union([createDiagramSchema, generationBatchSchemas['create-diagram']]), 'extend-diagram': z.union([extendDiagramSchema, generationBatchSchemas['extend-diagram']]), 'edit-diagram-status': diagramEditRunSchema,
  'cancel-diagram-edit': diagramEditRunSchema, create_diagram_change_session: createChangeSessionSchema, update_diagram_change_session: updateChangeSessionSchema, accept_diagram_change_session: acceptChangeSessionSchema, 'diagram-search': searchSchema, 'canvas-api-search': apiSearchSchema, exec: execSchema, draw_diagram: drawSchema, save_diagram: saveSchema, set_diagram_source_mappings: setSourceMappingsSchema };
export type AgentToolName = keyof typeof agentToolSchemas;

const apiJump = diagramJumpSchema.extend({ source: diagramJumpSchema.shape.source.omit({ contentHash: true }).extend({ contentHash: diagramJumpSchema.shape.source.shape.contentHash.optional() }), status: z.enum(['active', 'stale']).optional() });
export const canvasMethods = {
  'nodes.variants': { schema: z.object({ nodeId: idSchema }).strict(), description: 'Read retained variants and per-logical-node review changes for a diagram. Includes candidate ASCII, decisions and structural dependency errors. Does not mutate.', example: 'return nodes.variants({nodeId:"grid:overview"});' },
  'nodes.reviewVariant': { schema: z.object({ nodeId: idSchema, variantId: idSchema, decisions: z.record(idSchema, z.enum(['accept', 'reject'])).optional(), name: z.string().trim().min(1).max(120).optional(), remove: z.boolean().optional(), apply: z.boolean().optional() }).strict(), description: 'Save accept/reject decisions for variant change IDs. apply:true applies reviewed changes only, preserving unrelated edits and checking conflicts. Changing decisions and applying again reverses prior accepted changes. Structural dependencies must agree. Supports rename and remove. Requires expectedVersion; undoable and autosaved.', example: 'return nodes.reviewVariant({nodeId:"grid:overview",variantId,decisions,apply:true});' },
  'canvas.read': { schema: z.object({ level: z.enum(['small', 'full']).default('small'), nodeIds: z.array(idSchema).max(2000).optional() }).strict(), description: 'Read current canvas state without history. Small includes diagram text, anchors, complete source mappings/evidence, highlights, collapse state and jumps. Full adds layout, groups, floating objects, connections and view. IDs are immutable read-scoped aliases. Use returned version as expectedVersion for mutations. Filter nodeIds to limit large canvases.', example: 'return canvas.read({level:"small"});' },
  'nodes.highlight': { schema: highlightTargetsSchema.safeExtend({ nodeId: idSchema, color: highlightColorSchema.optional() }).strict(), description: 'Save one colored highlight on a diagram, one contentNodeId, or multiple contentNodeIds in that diagram. A group shares one saved ID, color, and link; removing that ID removes the group. Omit both target fields for the whole diagram. Optional color defaults to yellow; accepts yellow, blue, green, pink, purple, orange or #RRGGBB. Read current content-node anchors first. Repeating the same target set (in any order) updates its color and preserves its highlight ID. Highlights are diagram annotations shared by its instances, undoable and persisted automatically. Read diagram.highlights for IDs and targets. If any target changes, the whole group stays saved but stale until refreshed. Requires expectedVersion.', example: 'return nodes.highlight({nodeId:"grid:overview",contentNodeId:anchor.id,color:"blue"});' },
  'nodes.removeHighlights': { schema: z.object({ nodeId: idSchema, highlightIds: z.array(idSchema).min(1).max(2000).optional() }).strict(), description: 'Remove saved highlights from a diagram. Supply highlightIds from diagram.highlights to remove specific annotations (including stale ones), or omit highlightIds to remove all. Undoable and persisted automatically. Requires expectedVersion.', example: 'return nodes.removeHighlights({nodeId:"grid:overview",highlightIds:["highlight-…"]});' },
  'nodes.setSourceMappings': { schema: z.object(sourceMappingsFields).strict(), description: 'Replace the complete source mappings and evidence without changing ASCII, content anchors, or layout. Requires current expectedVersion; content checks are internal. Omitted source preserves the repository binding; empty mappings/evidence clears mappings. Undoable and persisted in workspace history; proposal calls stay isolated.', example: 'return nodes.setSourceMappings({nodeId:"grid:overview",mappings,evidence});' },
  'nodes.patchDiagram': { schema: z.object({ nodeId: idSchema, start: z.number().int().positive(), end: z.number().int().positive(), patch: z.string().max(20000) }).strict(), description: 'Replace 1-based inclusive raw ASCII lines. Empty patch deletes lines; trailing newline inserts a blank line. Ranges address the current document (later calls see earlier committed edits). Untouched mappings and source jumps shift; intersecting mappings are removed and changed anchors remain stale. Shared content updates all its instances. Undoable; no save.', example: 'return nodes.patchDiagram({nodeId:"grid:overview",start:2,end:3,patch:"|-- Updated"});' },
  'nodes.setJumps': { schema: z.object({ nodeId: idSchema, jumps: z.array(apiJump).max(2000) }).strict(), description: 'Replace diagram-local jumps without changing ASCII. Source ranges are original 1-based inclusive columns on the current content revision; content hashes are filled internally; contentNodeId is optional. Target representationId is a saved catalog canvas ID, not a live canvasId. Empty list removes all jumps. Undoable; explicit save required.', example: 'return nodes.setJumps({nodeId:"grid:overview",jumps:[]});' },
  'edges.list': { schema: z.object({}).strict(), description: 'Read saved diagram connections. Endpoint displayNodeId identifies a GridBox instance; contentNodeId and revisionId come from nodes.get content.structure.nodes and content. Short content-node handles are shared with live WebSocket context; full IDs remain accepted.', example: 'return edges.list();' },
  'edges.create': { schema: diagramConnectionSchema.omit({ id: true }), description: 'Connect a content node to another content node or GridBox. Endpoint side: horizontal chooses left/right by route cost; auto (default) compares all four sides; left/right/top/bottom fixes the side. appearance.label accepts {text, position?:{x,y}}; position is the label horizontal center and text baseline in absolute unscaled canvas pixels. Omit position for automatic placement. Legacy string labels remain supported. Does not change diagram content.', example: 'return edges.create({source, target, appearance:{color:"#7dd3fc",lineStyle:"solid",label:{text:"Uses",position:{x:400,y:180}}}});' },
  'edges.update': { schema: diagramConnectionSchema, description: 'Replace a connection by ID, including endpoints or appearance. Endpoint side: horizontal chooses left/right by route cost; auto compares all four sides; left/right/top/bottom fixes the side. appearance.label accepts {text, position?:{x,y}} in absolute unscaled canvas pixels (horizontal center, text baseline); omit position to restore automatic placement. Unchanged stale endpoints may be retained.', example: 'return edges.update({...edge, appearance:{...edge.appearance,label:{text:"Uses",position:{x:400,y:180}}}});' },
  'edges.remove': { schema: z.object({ edgeId: idSchema }).strict(), description: 'Remove one connection without deleting either diagram.', example: 'return edges.remove({edgeId:"…"});' },
  'canvas.list': { schema: z.object({}).strict(), description: 'List registered live Mapping pages and their documents.', example: 'return canvas.list();' },
  'canvas.attach': { schema: z.object({ canvasId: idSchema, documentId: idSchema }).strict(), description: 'Bind a new session to a live document. Use returned sessionId on subsequent calls.', example: 'return canvas.attach({canvasId:"…",documentId:"…"});' },
  'canvas.createDocument': { schema: z.object({ repositoryId: idSchema.optional(), canvasId: idSchema, name: z.string().trim().min(1).max(120) }).strict(), description: 'Create an unsaved document and attach a session. Does not create a confirmed representation.', example: 'return canvas.createDocument({canvasId:"…",name:"Proposed design"});' },
  'canvas.copyDocument': { schema: z.object({ repositoryId: idSchema.optional(), canvasId: idSchema, documentId: idSchema, name: z.string().trim().min(1).max(120), expectedVersion: z.number().int().nonnegative().optional() }).strict(), description: 'Copy a live document, including unsaved edits, diagrams, mappings, edges, layout and pane presentation, into an independent unsaved draft with a fresh undo baseline. Returns its attachment. Optional expectedVersion checks the source. Use an unbound exec without sessionId or changeSessionId. Does not publish or modify the source; transient controls and pending requests are reset.', example: 'return canvas.copyDocument({canvasId:"…",documentId:"…",name:"Canvas copy",expectedVersion:0});' },
  'nodes.list': { schema: z.object({}).strict(), description: 'Read the compact API DisplayNode registry (apiFormatVersion: 1). Diagram ASCII is in content; anchors are in content.structure.nodes for both trees and unstructured diagrams. diagram contains metadata only.', example: 'return nodes.list();' },
  'nodes.get': { schema: z.object({ nodeId: idSchema }).strict(), description: 'Read a compact API DisplayNode. Read ASCII from content.ascii and anchors from Object.values(content.structure.nodes); diagram.content and contentNodes are omitted. Handles are opaque, revision-scoped, shared across API/WebSocket reads, and expire on backend restart.', example: 'return nodes.get({nodeId:"grid:overview"});' },
  'nodes.draw': { schema: z.object({ ...contentFields, parentId: idSchema.optional(), position: point.optional() }).strict(), description: 'Create a diagram; natural content size feeds push-right grid layout. Position is parent-relative cells.', example: 'return nodes.draw({ascii:"[Service]",position:{column:0,row:0}});' },
  'nodes.replace': { schema: z.object({ nodeId: idSchema, ...contentFields }).strict(), description: 'Replace diagram content and rerun layout.', example: 'return nodes.replace({nodeId:"grid:overview",ascii:"[Updated]"});' },
  'nodes.move': { schema: z.object({ nodeId: idSchema, position: z.union([point, z.object({ x: z.number().finite(), y: z.number().finite() }).strict()]) }).strict(), description: 'Move GridBoxes in absolute canvas cells; FloatingBoxes in pixels in their declared coordinate space.', example: 'return nodes.move({nodeId:"grid:overview",position:{column:20,row:4}});' },
  'nodes.collapse': { schema: z.object({ nodeId: idSchema, contentNodeId: idSchema.optional(), collapsed: z.boolean() }).strict(), description: 'Collapse/expand a DisplayNode, or a content subtree using contentNodeId from node.collapsible.subtrees.', example: 'return nodes.collapse({nodeId:"grid:overview",collapsed:true});' },
  'nodes.remove': { schema: z.object({ nodeId: idSchema }).strict(), description: 'Remove an object. The root and last visible diagram are protected.', example: 'return nodes.remove({nodeId:"floating:…"});' }
} as const;
export function canvasApiSpec(query: string) {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  return Object.entries(canvasMethods).filter(([name, entry]) => terms.every(term => `${name} ${entry.description}`.toLowerCase().includes(term)))
    .map(([name, entry]) => ({ name, description: entry.description, inputSchema: z.toJSONSchema(entry.schema), example: entry.example }));
}
export interface CanvasDescriptor { canvasId: string; stableWorkspaceId?: string; projectId?: string; documents: { documentId: string; name: string; repositoryId?: string; representationId?: string }[] }
export interface CanvasCommand { id: string; method: 'identity' | 'read' | 'checkpoint' | 'snapshot' | 'context' | 'document-state' | 'apply' | 'apply-diagram-revision' | 'apply-diagram-batch' | 'canvas-view' | 'apply-diagram-context' | 'create-diagrams' | 'create-document' | 'copy-document' | 'saved'; documentId?: string; payload?: unknown }
export type LiveDocumentState = Pick<LiveDocumentSnapshot, 'document' | 'name'>;
export interface LiveDocumentSnapshot {
  contextId?: string;
  revisions?: import('../../core/diagrams/diagramRevisionEditor').DiagramRevision[];
  history?: import('../workspace/canvasHistory').CanvasHistoryRecord;
  endpointBounds?: import('../workspace/endpointGeometry').EndpointBounds;
  cell?: { width: number; height: number };
  document: import('../workspace/mappingGrid').MappingGridDocument;
  canvas: import('../workspace/mappingWorkspace').MappingCanvasState;
  version: number; name: string; repositoryId?: string; representationId?: string; revisionId?: string;
}

